mapper.select:
select o.id as id, o.transfer_request_no as requestNo, o.status as status, coalesce(nullif(trim(st.dict_label), ''), o.status) as statusLabel, o.transfer_fm_wh_cd as sourceWhCd, coalesce(nullif(fw.wh_nm, ''), o.transfer_fm_wh_cd) as sourceWarehouse, o.transfer_to_wh_cd as destWhCd, coalesce(nullif(tw.wh_nm, ''), o.transfer_to_wh_cd) as destWarehouse, nullif(o.transfer_ship_date, '') as desiredDate, nullif(o.transfer_date, '') as requestDate, coalesce(nullif(trim(ru.nick_name), ''), o.registered_by) as registrar, coalesce(nullif(trim(cu.nick_name), ''), o.completed_by) as completer, nullif(o.registration_date, '') as registeredDate, nullif(o.completion_date, '') as completedDate, nullif(o.memo, '') as memo, o.requester_name as requester from bss_transfer_order o left join mast_warehouse fw on fw.wh_cd = o.transfer_fm_wh_cd left join mast_warehouse tw on tw.wh_cd = o.transfer_to_wh_cd left join sys_dict_data st on st.dict_type = 'bss_transfer_status' and st.dict_value = o.status left join sys_user ru on ru.user_name = o.registered_by left join sys_user cu on cu.user_name = o.completed_by where o.delete_flg = '0'
and o.transfer_request_no like concat('%', #{moveNo}, '%')
and o.transfer_fm_wh_cd = #{sourceWhCd}
and o.transfer_to_wh_cd = #{destWhCd}
and exists ( select 1 from bss_transfer_order_detail d where d.transfer_request_no = o.transfer_request_no and d.delete_flg = '0' and d.item_code like concat('%', #{itemCode}, '%') )
and exists ( select 1 from bss_transfer_order_detail d where d.transfer_request_no = o.transfer_request_no and d.delete_flg = '0' and d.item_name like concat('%', #{itemName}, '%') )
and ( o.registered_by like concat('%', #{registrar}, '%') or ru.nick_name like concat('%', #{registrar}, '%') )
and ( o.completed_by like concat('%', #{completer}, '%') or cu.nick_name like concat('%', #{completer}, '%') )
and >= #{registeredFrom}
and <= #{registeredTo}
and >= #{completedFrom}
and <= #{completedTo}
and o.status in
#{status}
order by o.update_time desc nulls last, o.transfer_request_no

select d.transfer_request_no as requestNo, d.item_code as itemCode, d.item_name as itemName from bss_transfer_order_detail d where d.delete_flg = '0' and d.transfer_request_no in
#{requestNo}
order by d.transfer_request_no, d.detail_no

select coalesce(max(detail_no), 0)
from bss_transfer_order_detail
where transfer_request_no = #{requestNo}

mapper.update:
update bss_transfer_order_detail set delete_flg = '1', update_time = now(), update_by = #{updateBy}, update_pg_id = #{updatePgId}, version = version + 1 where transfer_request_no = #{requestNo} and delete_flg = '0'
and detail_no not in
#{detailNo}
